blocks.code:
.sidebar {
  min-height: 100vh;  /* минимум — на весь экран */
}

.card {
  max-height: 400px;  /* максимум — 400px */
}

.block {
  width: auto;   /* занимает всю ширину родителя */
  height: auto;  /* подстраивается под контент */
}

/* content-box: width = 300px, итого = 300 + 20 + 20 = 340px */
.box-content {
  box-sizing: content-box;
  width: 300px;
  padding: 20px;
}

/* border-box: width = 300px, итого = ровно 300px */
.box-border {
  box-sizing: border-box;
  width: 300px;
  padding: 20px;
}

.card {
  width: 100%;
  max-width: 400px;
  min-height: 200px;
  padding: 24px;
  box-sizing: border-box;
  overflow: hidden;
}
